"""Trusted command-center shell over saved /ask evidence and review work."""
from pathlib import Path
from .runtime import CSS


def page():
    script = Path(__file__).with_name('action_center.js').read_text()
    return '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agere · Action center</title><style>''' + CSS + '''
.agere-wrap{max-width:1480px}h1{font-size:34px;letter-spacing:-1px;margin:18px 0 8px}h2{margin-top:0}button,input,select,textarea{font:inherit;color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:9px;background:var(--panel)}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}.primary{background:var(--accent);color:white;border:0}.toolbar{display:flex;flex-wrap:wrap;gap:10px;align-items:center}.grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(290px,1fr);gap:18px;margin:18px 0}.metrics{display:flex;gap:12px;margin:18px 0;flex-wrap:wrap}.metric{min-width:155px;padding:14px 20px;border:1px solid var(--line);border-radius:10px;background:var(--panel)}.metric b{display:block;font-size:28px}.metric span{color:var(--muted)}.scroll{max-height:530px;overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;padding:10px;border-bottom:1px solid var(--line);vertical-align:top}th{position:sticky;top:0;background:var(--panel)}summary{cursor:pointer}pre{white-space:pre-wrap;word-break:break-word;max-height:320px;overflow:auto}label{display:block;margin:12px 0 5px}textarea{width:100%;min-height:90px}input[type=text],select{max-width:100%;width:100%}.notice{padding:12px 16px;border-left:4px solid var(--accent-2);background:var(--chip);margin:12px 0}.card{padding:16px;border:1px solid var(--line);border-radius:10px;margin:12px 0;background:var(--panel)}.card header{display:flex;justify-content:space-between;gap:8px}.pill{border-radius:20px;padding:3px 10px;background:var(--chip);font-size:12px}.workgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:14px}.status{min-height:25px;color:var(--accent)}iframe{width:100%;min-height:850px;border:1px solid var(--line);border-radius:12px}.hidden{display:none!important}@media(max-width:850px){.grid{grid-template-columns:1fr}.metric{flex:1}h1{font-size:28px}}@media print{button,input,select,textarea{display:none}.scroll{max-height:none}}
</style></head><body><main class="agere-wrap"><div class="toolbar"><a href="/ask">← Ask Agere</a><a href="/action-center">Saved workspaces</a><span class="muted">Synthetic data · internal review</span></div><h1>From insight to action.</h1><p class="muted">Build a program around the evidence. Assign the next step. Keep track of what happens.</p><div id="status" class="status" role="status" aria-live="polite">Loading…</div><section id="saved"></section><div id="center" class="hidden"><section class="panel"><div class="pill">ORIGINAL QUESTION</div><h2 id="question"></h2><p id="headline"></p><div id="scope"></div><details><summary>Answer, sources and execution evidence</summary><pre id="evidence"></pre></details></section><div id="metrics" class="metrics"></div><div class="grid"><section class="panel"><h2>Build your cohort</h2><p class="muted">Select from this exact answer. Selection does not establish program eligibility.</p><div class="toolbar"><input id="search" type="search" placeholder="Search patient or returned detail" aria-label="Search cohort"><button id="select-visible">Select visible</button><button id="clear">Clear selection</button></div><p id="selection" class="muted"></p><div class="scroll"><table><thead><tr><th>Select</th><th>Patient</th><th>Evidence from this answer</th></tr></thead><tbody id="patients"></tbody></table></div></section><section class="panel"><h2>Prepare the next step</h2><label for="program">Program to review</label><select id="program"></select><ul id="requirements"></ul><label for="owner">Responsible person or team</label><input id="owner" type="text" placeholder="e.g. PharmD review team" maxlength="120"><label for="note">What should they investigate or prepare?</label><textarea id="note" maxlength="2000" placeholder="Describe the objective, missing evidence or follow-up needed."></textarea><button id="create" class="primary">Create review work</button><p class="muted">Creates saved internal tasks. Outreach, enrollment, devices and medication changes require separate authorization and connected execution.</p></section></div><section class="panel"><div class="toolbar"><h2>Program work</h2><button id="refresh">Refresh</button><button id="export">Export work CSV</button></div><p class="muted">Review complete means the review is complete. It does not mean a patient is enrolled or care was delivered.</p><label for="work-filter">Filter work</label><select id="work-filter"><option value="">All review states</option></select><div id="work" class="workgrid"></div></section><section class="panel" style="margin-top:18px"><h2>Build a custom deliverable</h2><p class="muted">Give a frontier model these saved results and work items to design an interactive view. Computed data stays attached; the generated view cannot dispatch work.</p><label for="brief">Describe the deliverable</label><textarea id="brief" placeholder="Build a program command center with filters for evidence gaps, owner and review status. Show where the team should focus next."></textarea><button id="compose" class="primary">Create with frontier model · API usage</button><p id="cost" class="muted"></p><div id="deliverables"></div><div id="preview"></div></section></div></main><script>''' + script + '</script></body></html>'
